target.css:
:root {
  --ink: #253342;
  --muted: #71808b;
  --paper: #fffdf8;
  --line: #dce4e5;
  --mint: #dff3e8;
  --mint-dark: #18755b;
  --coral: #ef715d;
  --blue: #4b91c9;
  --gold: #e6ab3f;
}

.repair-board {
  box-sizing: border-box;
  width: 480px;
  padding: 16px;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: var(--paper);
  color: var(--ink);
}

.repair-board * {
  box-sizing: border-box;
}

.board-header {
  display: flex;
  align-items: center;
  gap: 10px;
  padding-bottom: 14px;
  border-bottom: 1px solid var(--line);
}

.tool-mark {
  display: grid;
  width: 38px;
  height: 38px;
  place-items: center;
  border-radius: 12px;
  background: var(--mint);
  font-size: 19px;
}

.heading-copy {
  flex: 1;
}

.eyebrow,
.ticket-label {
  margin: 0;
  color: var(--muted);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

h1,
h2 {
  margin: 0;
}

h1 {
  margin-top: 2px;
  font-size: 20px;
  line-height: 1.1;
}

.open-badge {
  padding: 5px 8px;
  border-radius: 999px;
  background: var(--mint);
  color: var(--mint-dark);
  font-size: 12px;
  font-weight: 700;
}

.queue-grid {
  display: grid;
  grid-template-columns: 1.08fr 1fr;
  gap: 10px;
  padding: 14px 0;
}

.ticket-card,
.next-card {
  min-height: 118px;
  padding: 12px;
  border: 1px solid var(--line);
  border-radius: 12px;
}

.ticket-card {
  background: var(--mint);
}

h2 {
  margin-top: 8px;
  font-size: 17px;
  line-height: 1.1;
}

.ticket-meta {
  margin: 4px 0 12px;
  color: var(--muted);
  font-size: 12px;
}

.progress-row {
  display: flex;
  justify-content: space-between;
  color: var(--mint-dark);
  font-size: 12px;
  font-weight: 700;
}

.progress-track {
  display: block;
  height: 6px;
  margin-top: 6px;
  overflow: hidden;
  border-radius: 99px;
  background: var(--paper);
}

.progress-fill {
  display: block;
  width: 60%;
  height: 100%;
  border-radius: inherit;
  background: var(--mint-dark);
}

.queue-list {
  display: grid;
  gap: 8px;
  margin: 10px 0 0;
  padding: 0;
  list-style: none;
}

.queue-list li {
  display: grid;
  grid-template-columns: 8px 1fr auto;
  align-items: center;
  gap: 7px;
  color: var(--ink);
  font-size: 13px;
}

.queue-list strong {
  color: var(--muted);
  font-size: 11px;
}

.queue-dot,
.volunteer-dot {
  display: inline-block;
  width: 8px;
  height: 8px;
  border-radius: 50%;
}

.coral { background: var(--coral); }
.blue { background: var(--blue); }
.gold { background: var(--gold); }

.board-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 12px;
  border-top: 1px solid var(--line);
}

.board-footer p {
  display: flex;
  align-items: center;
  gap: 6px;
  margin: 0;
  color: var(--muted);
  font-size: 12px;
}

.volunteer-dot {
  background: var(--mint-dark);
}

button {
  border: 0;
  border-radius: 8px;
  padding: 8px 11px;
  background: var(--ink);
  color: var(--paper);
  font-size: 12px;
  font-weight: 700;
}

